    quantity INT,
    restocktype VARCHAR(255),
    subtotal DECIMAL(10,2),
    subtotalsetshopmoney TEXT,
    subtotalsetshopmoneyamount TEXT,
    subtotalsetshopmoneycurrencycode VARCHAR(255),
    subtotalsetpresentmentmoney TEXT,
    subtotalsetpresentmentmoneyamount TEXT,
    subtotalsetpresentmentmoneycurrencycode VARCHAR(255),
    totaltax DECIMAL(10,2),
    totaltaxsetshopmoney TEXT,
    totaltaxsetshopmoneyamount TEXT,
    totaltaxsetshopmoneycurrencycode VARCHAR(255),
    totaltaxsetpresentmentmoney TEXT,
    totaltaxsetpresentmentmoneyamount TEXT,
    totaltaxsetpresentmentmoneycurrencycode VARCHAR(255),
    lineitemadmingraphqlapiid VARCHAR(255),
    lineitemattributedstaffs TEXT,
    lineitemcurrentquantity INT,
    lineitemfulfillablequantity INT,
    lineitemfulfillmentservice TEXT,
    lineitemfulfillmentstatus VARCHAR(255),
    lineitemgiftcard BOOLEAN,
    lineitemgrams INT,
    lineitemname TEXT,
    lineitemprice TEXT,
    lineitempriceset TEXT,
    lineitempricesetshopmoney TEXT,
    lineitempricesetshopmoneyamount TEXT,
    lineitempricesetshopmoneycurrencycode VARCHAR(255),
    lineitempricesetpresentmentmoney TEXT,
    lineitempricesetpresentmentmoneyamount TEXT,
    lineitempricesetpresentmentmoneycurrencycode VARCHAR(255),
    lineitemproductexists BOOLEAN,
    lineitemproductid INT,
    lineitemproperties TEXT,
    lineitemquantity INT,
    lineitemrequiresshipping BOOLEAN,
    lineitemsku TEXT,
    lineitemtaxable BOOLEAN,
    lineitemtitle TEXT,
    lineitemtotaldiscount TEXT,
    lineitemtotaldiscountset TEXT,
    lineitemtotaldiscountsetshopmoney TEXT,
    lineitemtotaldiscountsetshopmoneyamount TEXT,
    lineitemtotaldiscountsetshopmoneycurrencycode VARCHAR(255),
    lineitemtotaldiscountsetpresentmentmoney TEXT,
    lineitemtotaldiscountsetpresentmentmoneyamt TEXT,
    lineitemtotaldiscountsetpresentmentmoneycurrcode VARCHAR(255),
    lineitemvariantid INT,
    lineitemvariantinventorymanagement TEXT,
    lineitemvarianttitle TEXT,
    lineitemvendor TEXT,
    lineitemtaxlines TEXT,
    lineitemduties TEXT,
    lineitemdiscountallocations TEXT,
    ordersid VARCHAR(255) NOT NULL,
    ordersrefundsid VARCHAR(255) NOT NULL,
    clientid VARCHAR(255) NOT NULL,
    organisationid VARCHAR(255) NOT NULL,
    etlinserttime DATETIME DEFAULT CURRENT_TIMESTAMP,
    etlupdatetime DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

-- Pattern: c{clientID}_shopify_{entity}
