-- OrdersShipLines Production Table
DROP TABLE IF EXISTS c{clientID}_shopify_ordersshiplines;
CREATE TABLE c{clientID}_shopify_ordersshiplines (
    id INT,
    carrieridentifier VARCHAR(255),
    code VARCHAR(255),
    discountedprice TEXT,
    discountedpricesetshopmoney TEXT,
    discountedpricesetshopmoneyamount TEXT,
    discountedpricesetshopmoneycurrencycode VARCHAR(255),
    discountedpricesetpresentmentmoney TEXT,
    discountedpricesetpresentmentmoneyamount TEXT,
    discountedpricesetpresentmentmoneycurrencycode VARCHAR(255),
    isremoved BOOLEAN,
    phone TEXT,
    price TEXT,
    pricesetshopmoney TEXT,
    pricesetshopmoneyamount TEXT,
    pricesetshopmoneycurrencycode VARCHAR(255),
    pricesetpresentmentmoney TEXT,
    pricesetpresentmentmoneyamount TEXT,
    pricesetpresentmentmoneycurrencycode VARCHAR(255),
    requestedfulfillmentserviceid VARCHAR(255),
    source VARCHAR(255),
    title TEXT,
    taxlines TEXT,
    discountallocations TEXT,
    ordersid VARCHAR(255) NOT NULL,
    clientid VARCHAR(255) NOT NULL,
    organisationid VARCHAR(255) NOT NULL,
    etlinserttime DATETIME DEFAULT CURRENT_TIMESTAMP,
    etlupdatetime DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id, organisationid)
);

